control.onControlLoad:
for (const name of ["buildWebApplicationsWithEpageStudio2"]) {
    const heading = ee.getControl(name);
    heading.setAttribute("role", "heading");
    heading.setAttribute("aria-level", "1");
}
for (const name of ["overviewWorkflow", "overviewComponents", "overviewTaskSet", "overviewFiles"]) {
    const heading = ee.getControl(name);
    heading.setAttribute("role", "heading");
    heading.setAttribute("aria-level", "2");
}
for (const name of ["designInEpageStudio2", "addApplicationLogic2", "publishWithEserver2"]) {
    const heading = ee.getControl(name);
    heading.setAttribute("role", "heading");
    heading.setAttribute("aria-level", "3");
}
const anchors = {"overview-workflow":"overviewWorkflow","overview-components":"overviewComponents","overview-task-set":"overviewTaskSet","overview-files":"overviewFiles"};
function showSection() {
    const section = anchors[location.hash.slice(1)];
    if (section) ee.getControl(section)?.scrollIntoView({block: "start"});
}
window.addEventListener("hashchange", showSection);
requestAnimationFrame(showSection);

control.onCreate:
const cell = sender.label.rows[0].cells[0];
const link = document.createElement("a");
link.href = "./features?v=native-panels";

link.textContent = cell.textContent;
cell.replaceChildren(link);

